contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address newOwner) public payable {
        require(newOwner != address(0), "zero owner would revert for a different reason");

        address beforeOwner = c.owner();

        bool reverted;
        try c.transferOwnership(newOwner) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // msg.sender is InvMutTest, but it deployed c, so it IS the owner and the call will not revert.
        // General rule over all inputs: unless the owner changed, the previous owner is preserved.
        address afterOwner = c.owner();
        assert(reverted || afterOwner == newOwner || afterOwner == beforeOwner);
    }

    receive() external payable {}
}

